--
-- Estructura de tabla para la tabla `turnos_intercambios`
--

DROP TABLE IF EXISTS `turnos_intercambios`;
CREATE TABLE IF NOT EXISTS `turnos_intercambios` (
  `Id_Intercambio` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `Id_Semana` bigint UNSIGNED NOT NULL,
  `Fecha` date NOT NULL,
  `Id_Solicitante` bigint UNSIGNED NOT NULL,
  `Id_Receptor` bigint UNSIGNED NOT NULL,
  `Id_Turno_Solicitante` bigint UNSIGNED NOT NULL,
  `Id_Turno_Receptor` bigint UNSIGNED NOT NULL,
  `Hora_Inicio_Solicitante` time NOT NULL,
  `Hora_Fin_Solicitante` time NOT NULL,
  `Hora_Inicio_Receptor` time NOT NULL,
  `Hora_Fin_Receptor` time NOT NULL,
  `Motivo` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Estado` enum('pendiente','aceptado','rechazado','cancelado','expirado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pendiente',
  `Respondido_Por` bigint UNSIGNED DEFAULT NULL,
  `Fecha_Respuesta` datetime DEFAULT NULL,
  `Fecha_Creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Fecha_Actualizacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`Id_Intercambio`),
  KEY `idx_intercambios_solicitante` (`Id_Solicitante`,`Estado`,`Fecha`),
  KEY `idx_intercambios_receptor` (`Id_Receptor`,`Estado`,`Fecha`),
  KEY `idx_intercambios_semana_fecha` (`Id_Semana`,`Fecha`),
  KEY `fk_intercambios_turno_solicitante` (`Id_Turno_Solicitante`),
  KEY `fk_intercambios_turno_receptor` (`Id_Turno_Receptor`),
  KEY `fk_intercambios_respuesta` (`Respondido_Por`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `turnos_semanas`
--

DROP TABLE IF EXISTS `turnos_semanas`;
CREATE TABLE IF NOT EXISTS `turnos_semanas` (
  `Id_Semana` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `Fecha_Inicio` date NOT NULL COMMENT 'Lunes de la semana',
  `Fecha_Fin` date NOT NULL COMMENT 'Domingo de la semana',
  `Estado` enum('borrador','publicado','pendiente_republicacion') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'borrador',
  `Publicado_Por` bigint UNSIGNED DEFAULT NULL,
  `Fecha_Ultima_Publicacion` datetime DEFAULT NULL,
  `Creado_Por` bigint UNSIGNED DEFAULT NULL,
  `Actualizado_Por` bigint UNSIGNED DEFAULT NULL,
  `Fecha_Creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Fecha_Actualizacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`Id_Semana`),
  UNIQUE KEY `ux_turnos_semanas_inicio` (`Fecha_Inicio`),
  KEY `fk_turnos_semanas_publicado_por` (`Publicado_Por`),
  KEY `fk_turnos_semanas_creado_por` (`Creado_Por`),
  KEY `fk_turnos_semanas_actualizado_por` (`Actualizado_Por`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Volcado de datos para la tabla `turnos_semanas`
