--
-- Estructura de tabla para la tabla `turnos_vacaciones`
--

DROP TABLE IF EXISTS `turnos_vacaciones`;
CREATE TABLE IF NOT EXISTS `turnos_vacaciones` (
  `Id_Vacacion` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `Id_Usuario` bigint UNSIGNED NOT NULL,
  `Fecha_Inicio` date NOT NULL COMMENT 'Primer dia de disfrute',
  `Fecha_Fin` date NOT NULL COMMENT 'Ultimo dia de disfrute',
  `Fecha_Regreso` date NOT NULL COMMENT 'Fecha prevista de reincorporacion',
  `Dias_Habiles` smallint UNSIGNED NOT NULL DEFAULT '15',
  `Estado` enum('programada','cancelada') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'programada',
  `Observaciones` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Creado_Por` bigint UNSIGNED DEFAULT NULL,
  `Actualizado_Por` bigint UNSIGNED DEFAULT NULL,
  `Fecha_Creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Fecha_Actualizacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`Id_Vacacion`),
  KEY `idx_turnos_vacaciones_usuario_fechas` (`Id_Usuario`,`Fecha_Inicio`,`Fecha_Fin`),
  KEY `fk_turnos_vac_creado` (`Creado_Por`),
  KEY `fk_turnos_vac_actualizado` (`Actualizado_Por`)
) ;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `usuarios`
--

DROP TABLE IF EXISTS `usuarios`;
CREATE TABLE IF NOT EXISTS `usuarios` (
  `Id_Usuario` bigint UNSIGNED NOT NULL,
  `Nombres_Apellidos` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `Telefono_Usuario` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Usuario` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `Correo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `Avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Contrasena` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `Id_Rol` bigint UNSIGNED DEFAULT NULL,
  `Id_Canal` bigint UNSIGNED DEFAULT NULL,
  `Activo` tinyint(1) DEFAULT '1',
  `Fecha_Creacion` datetime DEFAULT CURRENT_TIMESTAMP,
  `Fecha_Actualizacion` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`Id_Usuario`),
  UNIQUE KEY `ux_usuarios_usuario` (`Usuario`),
  UNIQUE KEY `ux_usuarios_correo` (`Correo`),
  KEY `idx_usuarios_rol` (`Id_Rol`),
  KEY `fk_usuarios_canal` (`Id_Canal`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

